/* 		Exercise 5: Default/Parameterized Constructor				Practice Problem: Implement the Rectangle class (from Exercise 1). This time, include two public constructors: a default constructor that sets both length and width to 1, and a parameterized constructor that allows setting custom values for length and width.				Expected Output:		Custom Rectangle created (12x4).		R1 Area: 48		Default Rectangle created (1x1).		R2 Area: 1*/#include<iostream>class Rectangle{	private:	int length ;	int width ;	public:	Rectangle():length(1),width(1){	std::cout << "Default Rectangle Created (1X1)" << std::endl;	}		Rectangle(int len , int wid):length(len),width(wid){	std::cout << "Custom Rectangle Created (12X4)" <<std::endl;	}		int getArea()	{	return length * width;	}		};int main(void){	Rectangle R1;	std::cout << "R1 Area : " << R1.getArea() << std::endl;		Rectangle R2(12,4);	std::cout << "R2 Area : " << R2.getArea() << std::endl;		return 0;}